import { rmSync, writeFileSync } from "node:fs";

import { expect, expectStatus, sample, test } from "../../fixtures";

test("An expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs, factory }) => {
  // Arrange: a certificate that expired yesterday (local date, as the API's date.today()).
  const reviewer = await apiAs("reviewer");
  const now = new Date();
  const yesterday = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
  const expiry = [
    yesterday.getFullYear(),
    String(yesterday.getMonth() + 1).padStart(2, "0"),
    String(yesterday.getDate()).padStart(2, "0"),
  ].join("-");
  const file = `insurance_certificate_expired_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}.txt`;
  writeFileSync(
    sample(file),
    `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${expiry}\n`,
  );
  let arranged;
  try {
    arranged = await factory.vendorInReview({ files: { insurance_certificate: file } });
  } finally {
    rmSync(sample(file), { force: true });
  }
  const { documents, extractions } = arranged;

  // Act
  const response = await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("insurance_expired");
  expect((await factory.extraction(documents.insurance_certificate.id, "reviewer")).status).toBe("pending_review");
});
